message.content:
{
  "description": "A quadrupedal chimera shown in right-facing profile standing on a plain light background. The front of the animal including the head, neck, and forelegs, and the rear including the hindquarters, hind legs, and long bushy tail are covered in reddish-brown fox fur, while the mid-body, chest, and sides bear the plumage and folded wings of a barn owl. The head is fox-like with a pointed muzzle, the body is stout and low to the ground, and a single long fox tail lies on the ground behind the hind legs extending to the right.",
  "parts": [
    {
      "part": "head",
      "looks_like": "fox-like head at the front of the body in profile facing right, with reddish-orange fur on the crown and cheeks, white fur on the muzzle, lower jaw and throat, a black nose at the tip of a pointed snout, a visible yellow-brown eye with a dark pupil, fine whiskers on the muzzle, and a slightly open mouth",
      "where": "at the anterior end of the body atop the neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with reddish outer fur, black tips and edges, and pale cream to white inner fur with dark interior shading",
      "where": "on top of the head, one fully visible in profile and the second partially visible behind it on the far side"
    },
    {
      "part": "legs",
      "looks_like": "four slender digitigrade legs covered in reddish-brown fur that darkens to dark brown to black on the lower forelegs and hind legs, with visible joints and musculature",
      "where": "under the torso, two forelegs beneath the chest and two hind legs beneath the hindquarters, all supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "four paws with dark brown to black fur, rounded toe pads and short light-colored claws, the hind paws slightly more angled",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick, bushy tail covered in dense reddish-brown fur with a paler whitish tip, tapering slightly toward the end",
      "where": "extending from the rear of the hindquarters backward and to the right, lying along the ground behind and between the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "large folded bird wings with barn-owl patterning: upper coverts mottled tan, grey and white with small black spots, and long barred flight feathers cream and pale tan with dark brown to black bars and spots; one large wing is fully visible folded against the side, and a narrow edge of the opposite wing is visible on the far side of the chest",
      "where": "folded against the left and right sides of the mid-torso, covering the flank from behind the shoulder to above the hind leg"
    },
    {
      "part": "feathers",
      "looks_like": "soft dense feathers covering the ventral neck, chest and wing surfaces; chest and throat feathers are white to pale buff and fluffy with scattered small black spots, wing feathers are smooth and patterned as described for the wings",
      "where": "on the throat, chest, underside of the neck, and forming the entire surface of the wings on the sides of the body"
    },
    {
      "part": "markings",
      "looks_like": "small black spots scattered over the pale chest, throat and neck and over the tan and grey wing coverts, plus dark brown to black transverse bars and spots on the cream flight feathers",
      "where": "across the neck, chest, and the folded wing surfaces"
    }
  ],
  "attached_objects": [],
  "animals": [
    "fox",
    "barn owl"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
